// Grundlagen für Marken-Illustrationen (Team T7, siehe docs/DESIGN.md „Illustrationsstil“).
// Isometrie 30°, flache Flächen in drei Helligkeiten je Körper (oben hell,
// links mittel, rechts dunkel), 1,5-px-Konturen in Navy, keine Verläufe
// außer Himmel/Schein, keine Personen mit Gesichtern.

/** Illustrations-Palette (nur Markenskalen). */
export const ILLU = {
  // Körper grün (Vegetation, Agri-PV, Marke)
  gruenOben: "#cde3b1",
  gruenLinks: "#8cba58",
  gruenRechts: "#669933",
  gruenTief: "#436621",
  // Module / Technik (Navy)
  modulOben: "#1f5aa1",
  modulLinks: "#0b4488",
  modulRechts: "#003473",
  modulGlanz: "#7fa7d6",
  // Gebäude, Gestelle, Wege (neutral)
  hellOben: "#ffffff",
  hellLinks: "#eef0f4",
  hellRechts: "#dfe3ea",
  // Boden, Papier
  boden: "#f5f3ea",
  bodenDunkel: "#ebe7d8",
  // Akzente
  sonne: "#ffc53d",
  sonneHell: "#ffd873",
  strom: "#669933", // Energiefluss-Linien
  kontur: "#03285a",
  // Auf Navy-Grund
  nachtKontur: "rgba(255,255,255,0.18)",
};

const COS30 = Math.cos(Math.PI / 6);
const SIN30 = 0.5;

/**
 * Isometrische Projektion: Raumkoordinaten (x nach rechts-vorn, y nach
 * links-vorn, z nach oben) → SVG-Punkt. einheit = Pixel je Raumeinheit.
 */
export function iso(x, y, z = 0, einheit = 10, ursprung = [0, 0]) {
  return [ursprung[0] + (x - y) * COS30 * einheit, ursprung[1] + (x + y) * SIN30 * einheit - z * einheit];
}

/** Punkteliste → SVG-points-String. */
export function punkte(liste) {
  return liste.map(([a, b]) => `${a.toFixed(1)},${b.toFixed(1)}`).join(" ");
}

/**
 * Quader in Isometrie als drei Polygone (oben, links, rechts).
 * Rückgabe: { oben, links, rechts } als points-Strings.
 */
export function quader(x, y, z, b, t, h, einheit = 10, ursprung = [0, 0]) {
  const p = (a, c, d) => iso(a, c, d, einheit, ursprung);
  return {
    oben: punkte([p(x, y, z + h), p(x + b, y, z + h), p(x + b, y + t, z + h), p(x, y + t, z + h)]),
    links: punkte([p(x, y + t, z), p(x + b, y + t, z), p(x + b, y + t, z + h), p(x, y + t, z + h)]),
    rechts: punkte([p(x + b, y, z), p(x + b, y + t, z), p(x + b, y + t, z + h), p(x + b, y, z + h)]),
  };
}
import { cn } from "./cn";

/**
 * Rahmen für Marken-Illustrationen (SVG von T7 unter src/components/illustrationen).
 * Liefert Fläche, Raster, Lichtschein und feste Seitenverhältnisse, damit
 * nichts springt. Die Illustration selbst füllt den Rahmen (width/height 100 %).
 *
 * ton:    sand (Standard) | gruen | navy | weiss
 * format: "16/10" | "4/3" | "1/1" | "4/5" | "21/9" (CSS aspect-ratio)
 * raster: feines Hilfsraster im Hintergrund
 * schein: weicher Lichtfleck (Markengrün)
 * unterschrift: optionale Bildunterschrift (figcaption)
 * label:  Alternativtext, wenn die Illustration Inhalt trägt; sonst dekorativ
 */
const TOENE = {
  sand: "bg-sand-50 ring-1 ring-sand-200",
  gruen: "bg-ov-50 ring-1 ring-ov-100",
  navy: "ov-verlauf-nacht ring-1 ring-white/10 text-white",
  weiss: "bg-white ring-1 ring-ink-200/70",
};

export default function IllustrationRahmen({ ton = "sand", format = "16/10", raster = true, schein = true, unterschrift, label, className, innenClassName, children }) {
  const dunkel = ton === "navy";
  return (
    <figure className={cn("relative", className)}>
      <div
        role={label ? "img" : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : true}
        className={cn("relative isolate overflow-hidden rounded-[2rem]", TOENE[ton] || TOENE.sand)}
        style={{ aspectRatio: format }}
      >
        {raster && <div aria-hidden="true" className={cn("absolute inset-0 -z-10", dunkel ? "ov-grid-bg" : "ov-grid-bg-light")} />}
        {schein && (
          <div
            aria-hidden="true"
            className={cn("absolute -right-1/4 -top-1/3 -z-10 h-[90%] w-[70%] rounded-full blur-3xl", dunkel ? "bg-ov-500/25" : "bg-ov-200/50")}
          />
        )}
        <div className={cn("absolute inset-0 flex items-center justify-center p-[6%]", innenClassName)}>{children}</div>
      </div>
      {unterschrift && <figcaption className="mt-3 text-[13px] leading-snug text-ink-500">{unterschrift}</figcaption>}
    </figure>
  );
}
