/* Bewegungen der Marken-Illustrationen (Team T7, docs/DESIGN.md § 5).
   Nur transform, opacity und stroke-dashoffset. Aktiv nur, wenn die
   Illustration mit animiert gerendert wird (Klasse .an am svg) und das
   System keine reduzierte Bewegung verlangt. */

.illu {
  display: block;
  overflow: visible;
}

.rotor,
.strahlen,
.wolke,
.schweben,
.puls,
.kreis {
  transform-box: fill-box;
  transform-origin: center;
