      <Wolke f={f} x={320} y={44} />
      <Block r={r} x={0} y={0} b={26} t={18} h={Z} m={f.wiese} />
      <Flaeche r={r} fill={f.sand[0]} x0={11.4} y0={1.6} x1={21.6} y1={12.6} />
      {[1.8, 5.2, 8.6].map((y) => (
